const items = $input.all();
const formatted = [];

for (const item of items) {
  const execution = item.json.execution || {};
  const workflow = item.json.workflow || {};
  const error = execution.error || {};

  const alert = {
    severity: 'ERROR',
    service: 'LendLoop n8n Automation',
    workflowId: workflow.id || 'unknown',
    workflowName: workflow.name || 'Unknown Workflow',
    executionId: execution.id || 'unknown',
    executionUrl: execution.url || '',
    failedNode: execution.lastNodeExecuted || 'unknown',
    errorMessage: error.message || 'Unknown error occurred',
    timestamp: new Date().toISOString(),
  };

  console.error('[LendLoop Error Handler]', JSON.stringify(alert));
  formatted.push({ json: alert });
}

return formatted;
